import{_ as a,o,c as t,a4 as d}from"./chunks/framework.C83Ss68L.js";const g=JSON.parse('{"title":"Upgrade to v5","description":"Migrating KatanaKit from 4.x to 5 — no breaking changes, one runtime schema change in the WordPress adapter.","frontmatter":{"title":"Upgrade to v5","description":"Migrating KatanaKit from 4.x to 5 — no breaking changes, one runtime schema change in the WordPress adapter."},"headers":[],"relativePath":"guides/upgrade-to/v5.md","filePath":"guides/upgrade-to/v5.md","lastUpdated":1791014171000}'),i={name:"guides/upgrade-to/v5.md"};function s(r,e,n,c,l,h){return o(),t("div",null,[...e[0]||(e[0]=[d('<h1 id="upgrade-to-katanakit-v5" tabindex="-1">Upgrade to KatanaKit v5 <a class="header-anchor" href="#upgrade-to-katanakit-v5" aria-label="Permalink to &quot;Upgrade to KatanaKit v5&quot;">​</a></h1><p>This guide migrates you from <strong>4.x</strong> to <strong>5.x</strong>.</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> katanakit-js@^5</span></span></code></pre></div><h2 id="breaking-changes" tabindex="-1">Breaking changes <a class="header-anchor" href="#breaking-changes" aria-label="Permalink to &quot;Breaking changes&quot;">​</a></h2><p>None. The 5.x series carries no <code>Breaking</code> entries in the <a href="/katanakit-js/changelog">changelog</a>: 5.0.0 was a version-alignment release (GitHub tag only, superseded hours later by 5.0.1) and everything after it was additive.</p><h2 id="behaviour-change-worth-knowing" tabindex="-1">Behaviour change worth knowing <a class="header-anchor" href="#behaviour-change-worth-knowing" aria-label="Permalink to &quot;Behaviour change worth knowing&quot;">​</a></h2><p><strong><code>WpEmbedded[&quot;wp:featuredmedia&quot;]</code> shape</strong> (5.1.0) — it is now a loose partial shape instead of <code>WpMedia[]</code>. Embedded media never nests its own <code>_embedded</code>, which broke the Zod schema cycle. <code>source_url</code>, <code>id</code> and <code>title</code> stay typed, but if you were reading a full media array out of <code>_embedded</code> you now get the partial.</p><p>If you only read <code>post._embedded[&quot;wp:featuredmedia&quot;][0].source_url</code>, nothing changes.</p><h2 id="added-in-v5" tabindex="-1">Added in v5 <a class="header-anchor" href="#added-in-v5" aria-label="Permalink to &quot;Added in v5&quot;">​</a></h2><ul><li><strong>Zod validation across the library</strong> (5.1.0) — <code>zod</code> is a dependency and runtime schemas live behind the new <code>katanakit-js/schemas</code> subpath. <code>src/types/</code> now infers via <code>z.infer</code>, so consumer imports do not change. New <code>useValidate()</code> returns a Safe Result instead of throwing.</li><li><strong>InsForge adapter</strong> (5.1.0) — <code>katanakit-js/adapters/insforge</code>, an optional <code>@insforge/sdk</code> peer, with database, storage and edge-function helpers. Mass writes are refused (update/delete require a non-empty filter) and the whole surface returns Safe Results.</li><li><strong>SmartVideo and YouTube services</strong> (5.1.0) — media parsing, embed building and quota-cheap channel listings with a keyless RSS fallback.</li><li><strong>Filesystem service</strong> (5.1.1) — <code>useReadFile</code>, <code>useWriteFile</code>, <code>useReadDir</code> and friends for Node/Bun, every fallible call returning a Safe Result with the native errno <code>code</code>. Browsers and Workers get <code>ERR_FS_UNAVAILABLE</code> instead of a crash.</li><li><strong>Faker service</strong> (5.1.1) — <code>useFakeEmail</code>, <code>useFakeList</code>, <code>useFakeSeed</code> and the rest. <code>@faker-js/faker</code> is an optional peer loaded through dynamic <code>import()</code>, so it never enters the initial bundle.</li><li><strong>Safe Result helpers</strong> (5.2.0) — <code>useAttempt()</code>, <code>useTryJsonParse()</code> and <code>useErrorNormalize()</code> are now the recommended boundary helpers, and the ad-hoc <code>try/catch</code> blocks scattered through the library were collapsed into them. See the <a href="/katanakit-js/guides/errors">error handling guide</a>.</li><li><strong>Katana UI foundations</strong> (5.2.0) — <code>@katanakit/ui</code>, a private workspace with framework-agnostic <code>useButton</code>/<code>useInput</code>/<code>useCard</code>/<code>useBadge</code>/<code>useAlert</code> styled by <code>katanakit-css</code>. Not published to npm yet.</li><li><strong>Docs moved to VitePress</strong> (5.2.0) — sources live in <code>docs/</code> and are served at <code>docs.senseikatana.com/*</code>. Old <code>/docs/*</code> links redirect.</li></ul><h2 id="migration-checklist" tabindex="-1">Migration checklist <a class="header-anchor" href="#migration-checklist" aria-label="Permalink to &quot;Migration checklist&quot;">​</a></h2><ol><li>Install <code>katanakit-js@^5</code>.</li><li>If you use the WordPress adapter, re-read anything that consumed <code>_embedded[&quot;wp:featuredmedia&quot;]</code> as a full array.</li><li>Run your test suite — the rest is additive.</li></ol>',12)])])}const p=a(i,[["render",s]]);export{g as __pageData,p as default};
